effect.shader:
const int TAPS = 12;
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  vec3 acc = vec3(0.0);
  for (int i = 0; i < TAPS; i++){
    float ang = float(i) * 6.2831853 / float(TAPS);
    vec4 s = texture2DCv(inputImg.texture, uv + vec2(cos(ang), sin(ang)) * radius);
    vec3 sc = s.rgb / max(s.a, 1e-4);
    acc += sc * smoothstep(threshold, 1.0, gmLum(sc));
  }
  acc /= float(TAPS);
  vec3 col = vec3(1.0) - (vec3(1.0) - c) * (vec3(1.0) - acc * halColor.rgb * intensity * mixAmt);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0) * a, a);
}
